import sys

def max_digit_sum(x):
    x_str = str(x)
    n = len(x_str)

    # Start with the highest possible number with the same number of digits
    result = [9] * n

    for i in range(n):
        if int(''.join(map(str, result))) > x:
            result[i] -= 1
            result[i+1:] = [9] * (n - i - 1)
            break

    # Adjust the last digit if necessary
    if int(''.join(map(str, result))) > x:
        result[-1] -= 1

    return int(''.join(map(str, result)))

def main():
    import sys
    x = int(sys.stdin.read().strip())
    print(max_digit_sum(x))

if __name__ == "__main__":
    main()
